tool_input.command:
mkdir -p $TMPDIR/scratch && cat > $TMPDIR/scratch/Probe.java << 'EOF'
import java.io.Serializable;
import java.lang.reflect.Method;
import org.apache.commons.lang3.reflect.MethodUtils;

public class Probe {
    interface IfaceA {
        default void process(Number n) {}
    }
    interface IfaceB {
        default void process(Serializable s) {}
    }
    static class Multi implements IfaceA, IfaceB {}

    public static void main(String[] args) throws Exception {
        for (Method m : Multi.class.getMethods()) {
            if (m.getName().equals("process")) {
                System.out.println(m + " declaring=" + m.getDeclaringClass());
            }
        }
        try {
            Method r = MethodUtils.getMatchingMethod(Multi.class, "process", Integer.class);
            System.out.println("result=" + r);
        } catch (Exception e) {
            System.out.println("exception: " + e);
        }
    }
}
EOF
javac -cp target/classes -d $TMPDIR/scratch $TMPDIR/scratch/Probe.java && java -cp target/classes:$TMPDIR/scratch Probe
